dashboard.definition:
{
	"title": "Zero Trust Access",
	"description": "Secure Networking drill-down dashboard for Zero Trust Access.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$time_tok.earliest$",
						"latest": "$time_tok.latest$"
					}
				}
			},
			"ds.spl2": {
				"options": {
					"queryParameters": {
						"earliest": "$time_tok.earliest$",
						"latest": "$time_tok.latest$"
					}
				}
			}
		},
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#ffffff",
				"fontColor": "#111827",
				"markdown": "# Zero Trust Access\nIdentity enforcement, policy outcomes, ZTNA sessions, and authentication friction."
			}
		},
		"viz_zta_auth_events": {
			"type": "splunk.singlevalue",
			"title": "ISE Auth Events",
			"dataSources": {
				"primary": "ds_zta_auth_events"
			},
			"options": {
				"backgroundColor": "#ffffff",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('auth_events') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#0ea5e9"
			}
		},
		"viz_zta_failed_auth": {
			"type": "splunk.singlevalue",
			"title": "Failed Auth",
			"dataSources": {
				"primary": "ds_zta_failed_auth"
			},
			"options": {
				"backgroundColor": "#ffffff",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('failed_auth') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#dc2626"
			}
		},
		"viz_zta_failed_pct": {
			"type": "splunk.singlevalueradial",
			"title": "Auth Failure Rate",
			"dataSources": {
				"primary": "ds_zta_failed_pct"
			},
			"options": {
				"backgroundColor": "#ffffff",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('failed_pct') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('failed_pct') | lastPoint() | rangeValue(lowerBetter)",
				"unit": "%"
			},
			"context": {
				"lowerBetter": [
					{
						"to": 1,
						"value": "#16a34a"
					},
					{
						"from": 1,
						"to": 5,
						"value": "#eab308"
					},
					{
						"from": 5,
						"value": "#dc2626"
					}
				]
			}
		},
		"viz_zta_feed_health": {
			"type": "splunk.singlevalueradial",
			"title": "ISE Feed Age",
			"dataSources": {
				"primary": "ds_zta_feed_health"
			},
			"options": {
				"backgroundColor": "#ffffff",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('age_minutes') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('age_minutes') | lastPoint() | rangeValue(staleness)",
				"unit": "min"
			},
			"context": {
				"staleness": [
					{
						"to": 30,
						"value": "#16a34a"
					},
					{
						"from": 30,
						"to": 90,
						"value": "#eab308"
					},
					{
						"from": 90,
						"value": "#dc2626"
					}
				]
			}
		},
		"viz_zta_auth_outcome": {
			"type": "splunk.area",
			"title": "Authentication Outcome Trend",
			"dataSources": {
				"primary": "ds_zta_auth_outcome_trend"
			},
			"options": {
				"backgroundColor": "#ffffff",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#16a34a",
					"#dc2626",
					"#64748b"
				],
				"stackMode": "stacked",
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_zta_radius_latency": {
			"type": "splunk.line",
			"title": "RADIUS Latency by ISE Node",
			"dataSources": {
				"primary": "ds_zta_radius_latency"
			},
			"options": {
				"backgroundColor": "#ffffff",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#2563eb",
					"#16a34a",
					"#f59e0b",
					"#dc2626"
				],
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_zta_ztna_status": {
			"type": "splunk.area",
			"title": "ZTNA Connection Status",
			"dataSources": {
				"primary": "ds_zta_ztna_status"
			},
			"options": {
				"backgroundColor": "#ffffff",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#16a34a",
					"#f59e0b",
					"#dc2626",
					"#64748b"
				],
				"stackMode": "stacked",
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_zta_auth_by_device": {
			"type": "splunk.table",
			"title": "Auth Failure Rate by Network Device",
			"dataSources": {
				"primary": "ds_zta_auth_by_device"
			},
			"options": {
				"backgroundColor": "#ffffff",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		},
		"viz_zta_failure_reasons": {
			"type": "splunk.bar",
			"title": "Top Authentication Failure Reasons",
			"dataSources": {
				"primary": "ds_zta_failure_reasons"
			},
			"options": {
				"backgroundColor": "#ffffff",
				"legendDisplay": "off",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#dc2626"
				]
			}
		},
		"viz_zta_user_cross_source": {
			"type": "splunk.table",
			"title": "Cross-Source User Activity",
			"dataSources": {
				"primary": "ds_zta_user_cross_source"
			},
			"options": {
				"backgroundColor": "#ffffff",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		}
	},
	"dataSources": {
		"ds_base_zta_ise_auth": {
			"name": "Secure Networking base - ZTA ISE authentication events",
			"options": {
				"query": "`index_identity` sourcetype=\"cisco:ise:syslog\" (CISE_Passed_Authentications OR CISE_Failed_Attempts OR MESSAGE_CODE IN (5200,5201,5206,5232,5233,5236,5401,5440) OR log_type=\"Passed-Authentication\" OR log_type=\"Failed-Attempt\" OR log_type=\"Authentication\")\n| rex \"FailureReason=(?<reason_from_raw>[^,;]+)\"\n| rex field=Location \"Location#All Locations#(?<site_from_location>.*)\"\n| eval outcome=case(log_type=\"Failed-Attempt\" OR AuthenticationStatus=\"Fail\" OR AuthenticationStatus=\"Failed\" OR match(_raw,\"CISE_Failed\") OR MESSAGE_CODE=5401 OR MESSAGE_CODE=5440,\"Failure\", log_type=\"Passed-Authentication\" OR AuthenticationStatus=\"Pass\" OR AuthenticationStatus=\"Passed\" OR match(_raw,\"CISE_Passed\") OR MESSAGE_CODE=5200 OR MESSAGE_CODE=5201,\"Success\", 1==1,\"Other\")\n| eval is_failed=if(outcome=\"Failure\",1,0), site=coalesce(site_from_location, Location, \"Unknown\"), identity=coalesce(UserName, user, user_name, src_user, \"Unknown\"), endpoint=upper(replace(coalesce(EndPointMACAddress, Calling_Station_ID), \"-\", \":\")), failure_reason=coalesce(FailureReason, reason_from_raw, \"Unknown\")",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_zta_auth_events": {
			"name": "Secure Networking chain - ZTA auth event count",
			"options": {
				"extend": "ds_base_zta_ise_auth",
				"query": "| stats count as auth_events\n| eval label=\"ISE Authentication Events\"\n| fields label auth_events"
			},
			"type": "ds.chain"
		},
		"ds_zta_failed_auth": {
			"name": "Secure Networking chain - ZTA failed auth count",
			"options": {
				"extend": "ds_base_zta_ise_auth",
				"query": "| stats sum(is_failed) as failed_auth\n| eval label=\"ISE Failed Authentication Events\"\n| fields label failed_auth"
			},
			"type": "ds.chain"
		},
		"ds_zta_failed_pct": {
			"name": "Secure Networking chain - ZTA failure rate",
			"options": {
				"extend": "ds_base_zta_ise_auth",
				"query": "| stats count as total, sum(is_failed) as failed\n| eval failed_pct=if(total>0, round(failed/total*100,1), 0)\n| eval label=\"ISE Auth Failure Rate\"\n| fields label failed_pct failed total"
			},
			"type": "ds.chain"
		},
		"ds_zta_auth_outcome_trend": {
			"name": "Secure Networking chain - ZTA auth outcome trend",
			"options": {
				"extend": "ds_base_zta_ise_auth",
				"query": "| timechart span=1h count as Authentications by outcome"
			},
			"type": "ds.chain"
		},
		"ds_zta_auth_by_device": {
			"name": "Secure Networking chain - ZTA auth failure by device",
			"options": {
				"extend": "ds_base_zta_ise_auth",
				"query": "| where isnotnull(NetworkDeviceName) AND NetworkDeviceName!=\"\"\n| stats count as \"Total Auths\", sum(is_failed) as \"Failed Auths\", dc(identity) as \"Unique Users\" by NetworkDeviceName\n| eval \"Fail Rate %\"=if('Total Auths'>0, round('Failed Auths'/'Total Auths'*100,1), 0)\n| sort - \"Fail Rate %\" - \"Total Auths\"\n| head 20\n| rename NetworkDeviceName as \"Network Device\"\n| table \"Network Device\", \"Total Auths\", \"Failed Auths\", \"Fail Rate %\", \"Unique Users\""
			},
			"type": "ds.chain"
		},
		"ds_zta_failure_reasons": {
			"name": "Secure Networking chain - ZTA failure reasons by site",
			"options": {
				"extend": "ds_base_zta_ise_auth",
				"query": "| search outcome=\"Failure\"\n| stats count as Failures by site, failure_reason\n| rename site as \"Site\", failure_reason as \"Failure Reason\"\n| eval \"Site / Failure Reason\"='Site'.\" / \".'Failure Reason'\n| sort - Failures\n| head 15\n| table \"Site / Failure Reason\", Failures"
			},
			"type": "ds.chain"
		},
		"ds_zta_feed_health": {
			"name": "Feed Monitor - ISE - RADIUS Syslog Staleness (Signal Rail KPI)",
			"options": {
				"query": "| makeresults\n| eval count_24h=0, last_ts=0\n| append [| tstats count as count_24h latest(_time) as last_ts WHERE `index_identity` AND sourcetype=\"cisco:ise:syslog\"]\n| stats sum(count_24h) as count_24h max(last_ts) as last_ts\n| eval age_minutes=if(last_ts>0, round((now()-last_ts)/60, 0), 9999)\n| eval readiness=case(count_24h=0 OR last_ts=0,\"NOT ONBOARDED - add Splunk HF as ISE remote logging target\", age_minutes<=30,\"Active - last event \".tostring(age_minutes).\" min ago\", age_minutes<=90,\"WARNING - stale \".tostring(age_minutes).\" min - check ISE MnT remote logging targets\", 1==1,\"CRITICAL - STALE \".tostring(age_minutes).\" min - verify ISE syslog target config and TLS cert validity\")\n| eval last_seen=if(last_ts>0, strftime(last_ts,\"%Y-%m-%d %H:%M:%S\"), \"Never\")\n| fields count_24h age_minutes readiness last_seen",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_zta_radius_latency": {
			"name": "Security Resilience - ISE RADIUS Request Latency",
			"options": {
				"query": "`index_identity` sourcetype=\"cisco:ise:syslog\" MESSAGE_CLASS=\"System-Stats\"\n| timechart eval(round(avg(AverageRadiusRequestLatency), 2)) as avg_latency by ise_servername",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_zta_ztna_status": {
			"name": "Secure Networking - ZTA ZTNA Connection Status Trend",
			"options": {
				"query": "`index_security` sourcetype=\"cisco:cloud_security:ztnaflow\"\n| eval status=coalesce(action, connection_status, \"Unknown\")\n| timechart span=1h count by status",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_zta_user_cross_source": {
			"name": "Secure Networking - ZTA User Activity Cross-Source Correlation",
			"options": {
				"query": "(`index_identity` sourcetype=\"cisco:ise:syslog\" (log_type=\"Passed_Authentications\" OR log_type=\"Failed_Attempts\") UserName!=\"\") OR (`index_security` sourcetype=\"cisco:cloud_security:ztnaflow\" user!=\"\") OR (`index_firewall` sourcetype=\"cisco:ftd:syslog\" SourceSecurityGroup!=\"\")\n| eval identity=coalesce(UserName,user,\"Unknown\"), source_layer=case(sourcetype=\"cisco:ise:syslog\",\"ISE/NAC\",sourcetype=\"cisco:cloud_security:ztnaflow\",\"ZTNA\",sourcetype=\"cisco:ftd:syslog\",\"FMC Firewall\",1=1,\"Unknown\"), event_result=case(sourcetype=\"cisco:ise:syslog\" AND (log_type=\"Failed_Attempts\" OR action=\"failure\"),\"Fail\",sourcetype=\"cisco:ise:syslog\",\"Pass\",sourcetype=\"cisco:cloud_security:ztnaflow\",coalesce(connection_status,\"Allow\"),sourcetype=\"cisco:ftd:syslog\",coalesce(AC_RuleAction,\"Allow\"),1=1,\"Unknown\")\n| stats count as event_count, dc(source_layer) as layers_seen, values(source_layer) as sources, dc(eval(if(event_result=\"Fail\" OR event_result=\"Block\" OR event_result=\"Block with reset\",source_layer,null()))) as fail_layers, latest(_time) as last_seen by identity\n| eval \"Sources\"=mvjoin(sources,\", \"), \"Last Seen\"=strftime(last_seen,\"%Y-%m-%d %H:%M:%S\")\n| sort - event_count\n| head 25\n| rename identity as \"Identity\", event_count as \"Total Events\", layers_seen as \"Layers Seen\", fail_layers as \"Fail/Block Layers\"\n| table \"Identity\", \"Total Events\", \"Layers Seen\", \"Fail/Block Layers\", \"Sources\", \"Last Seen\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#f5f7fb",
					"display": "auto-scale",
					"height": 1490,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 90
						},
						"type": "block"
					},
					{
						"item": "viz_zta_auth_events",
						"position": {
							"x": 20,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_zta_failed_auth",
						"position": {
							"x": 375,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_zta_failed_pct",
						"position": {
							"x": 730,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_zta_feed_health",
						"position": {
							"x": 1085,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_zta_auth_outcome",
						"position": {
							"x": 20,
							"y": 310,
							"w": 690,
							"h": 340
						},
						"type": "block"
					},
					{
						"item": "viz_zta_radius_latency",
						"position": {
							"x": 730,
							"y": 310,
							"w": 690,
							"h": 340
						},
						"type": "block"
					},
					{
						"item": "viz_zta_ztna_status",
						"position": {
							"x": 20,
							"y": 670,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_zta_auth_by_device",
						"position": {
							"x": 730,
							"y": 670,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_zta_failure_reasons",
						"position": {
							"x": 20,
							"y": 1080,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_zta_user_cross_source",
						"position": {
							"x": 730,
							"y": 1080,
							"w": 690,
							"h": 390
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": true,
		"hideExport": false
	}
}
